((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, description, pixelWidth, pixelHeight}, i) => ({
      image: src, description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (material.answersFile ?? (reviewedKey ? 'reviewed-' + grade : grade + '-answers') + '.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2021, "8-9", [{"author":"И. Рубанов","question":"<em>Перечень</em> — это _____.","choices":["список","упрямец","мельница для перца","поперечный брус","спорщик."],"key":"А","review":["Значение слова «перечень»","«Перечень» связан с перечислением: предметы или пункты называют один за другим.","Перечень книг, услуг или документов — их список."]},{"author":"О. Подлесская","question":"Закончите историю так, чтобы получился анекдот: <em>Фокусник позвал на манеж из зрительного зала мальчика: ― Можешь ты, мальчик, подтвердить, что видишь меня впервые?</em>","choices":["<em>― Да, сэр.</em>","<em>― Да, сударь.</em>","<em>― Да, папа.</em>","<em>― Да, конечно.</em>","<em>― Да, могу.</em>"],"key":"В","review":["Реплика на манеже","Фокусник хочет подтвердить, что мальчик с ним не знаком. Большинство ответов просто выражают согласие.","«Да, папа» одновременно соглашается и выдаёт давнее знакомство. В этом и состоит шутка."]},{"author":"Е. Бикмаев","question":"В какой паре слова по смыслу соотносятся между собой не так, как в остальных?","choices":["<em>грешный — грешник</em>","<em>праведный — праведник</em>","<em>виновный — виновник</em>","<em>пленный — пленник</em>","<em>странный — странник</em>."],"key":"Д","review":["Прилагательное и человек","Грешник грешен, праведник праведен, виновник виноват, пленник находится в плену. Существительное называет того, к кому относится соответствующий признак.","Странник — тот, кто странствует. Он не обязательно странный, поэтому в этой паре смысловая связь другая."]},{"author":"И. Рубанов","question":"Выполняя домашнее задание, Таня выписала в тетрадь слова <em>граммофон</em>, <em>телефон</em>, <em>мегафон</em>, <em>саксофон</em>. Каким словом она может продолжить этот список?","choices":["<em>грифон</em>","<em>марафон</em>","<em>микрофон</em>","<em>плафон</em>","<em>сифон</em>."],"key":"В","review":["Общая часть названий","В «граммофоне», «телефоне», «мегафоне» и «саксофоне» часть «-фон» связана со звуком.","«Микрофон» тоже имеет отношение к звуку и содержит ту же часть. В других словах совпадает только окончание написания."]},{"author":"И. Рубанов","question":"Название каждого из минералов <em>гематит</em>, <em>лазурит</em>, <em>цитрин</em> связано с определённым цветом. Какое с каким?","choices":["<em>гематит</em> — с красным, <em>лазурит</em> — с голубым, <em>цитрин</em> — с жёлтым","<em>гематит</em> — с красным, <em>лазурит</em> — с жёлтым, <em>цитрин</em> — с голубым","<em>гематит</em> — с жёлтым, <em>лазурит</em> — с красным, <em>цитрин</em> — с голубым","<em>гематит</em> — с жёлтым, <em>лазурит</em> — с голубым, <em>цитрин</em> — с красным","<em>гематит</em> — с голубым, <em>лазурит</em> — с красным, <em>цитрин</em> — с жёлтым."],"key":"А","review":["Цвета в названиях минералов","«Гематит» связан с греческим названием крови, а «лазурит» напоминает слово «лазурь», название голубого цвета.","«Цитрин» напоминает жёлтый цитрус, лимон. Получаем по порядку красный, голубой и жёлтый."]},{"author":"П. Аркадьев","question":"В рекламе по радио сказали: <em>Трудно найти и связаться с клиентами</em>. А как выразить эту мысль правильно?","choices":["Всё и так правильно","<em>Трудно найти клиентов и связаться</em>","<em>Трудно найти и связать клиентов</em>","<em>Трудно найти их и связаться с клиентами</em>","<em>Трудно найти клиентов и связаться с ними</em>."],"key":"Д","review":["Управление двух глаголов","От «найти» задаём вопрос «кого?», а от «связаться» — «с кем?». Один и тот же падеж не отвечает на оба вопроса.","Нужно «найти клиентов и связаться с ними». Во второй части местоимение повторяет смысл первого дополнения в нужной форме."]},{"author":"О. Подлесская","question":"Название какого кухонного прибора устроено по смыслу не так, как остальные?","choices":["<em>овощерезка</em>","<em>картофелечистка</em>","<em>пароварка</em>","<em>чеснокодавилка</em>","<em>мясорубка</em>."],"key":"В","review":["Как устроены названия приборов","В овощерезке режут овощи, картофелечисткой чистят картофель, чеснокодавилкой давят чеснок, мясорубкой рубят мясо.","Пароварка готовит еду с помощью пара. Первая часть называет средство готовки, а не то, что готовят."]},{"author":"Л. Фёдорова","question":"Какое прилагательное отличается от остальных по составу?","choices":["<em>всероссийский</em>","<em>всесоюзный</em>","<em>всемирный</em>","<em>вселенский</em>","<em>всенощный</em>."],"key":"Г","review":["Части прилагательного","«Всероссийский», «всесоюзный», «всемирный» и «всенощный» относятся ко всей России, союзу, миру или всей ночи. Первая часть значит «весь».","«Вселенский» образовано от «вселенная». В нём нет отдельной части «все» со значением «весь»."]},{"author":"Б. Иомдин","question":"В какой паре слова могут быть антонимами?","choices":["<em>доделка — недоделка</em>","<em>палка — непалка</em>","<em>сушка — несушка</em>","<em>хватка — нехватка</em>","<em>явка — неявка</em>."],"key":"Д","review":["Наличие и отсутствие","«Доделка» — действие или результат доделывания, «недоделка» — недостаток работы. «Нехватка» тоже не противоположность «хватке».","«Явка» — присутствие там, где ожидали человека, «неявка» — отсутствие. Это противоположные ситуации."]},{"author":"А. Сомин","question":"<em>Могу я квакать, как лягушка,\nМогу гудеть, как паровоз,\nМогу я грохнуть, словно пушка,\nЧто я такое? — вот вопрос.\nА откликаюсь я (внимание!)\nНа имя ______.</em>\nКаким словом заканчивается стихотворение В. Агафонова?","choices":["<em>звуковосклицание</em>","<em>звукосочетание</em>","<em>звукосодержание</em>","<em>звукоподражание</em>","<em>звукоотражание</em>."],"key":"Г","review":["Подсказка в звуках","Герой стихотворения может воспроизвести кваканье, гудок или грохот. Все три примера показывают подражание услышанному.","Это явление называют «звукоподражание». Слово подходит и к смыслу, и к рифме с «внимание»."]},{"author":"И. Рубанов","question":"Вам выдали 1500 рублей. Значит, вы располагаете _____ рублей.","choices":["<em>полтора тысячами</em>","<em>полутора тысячами</em>","<em>полторами тысячами</em>","<em>полутора тысячей</em>","<em>полутора тысяч</em>."],"key":"Б","review":["Полторы тысячи","Глагол «располагать» требует творительного падежа: располагать чем? «тысячами рублей».","У числительного «полтора» косвенная форма «полутора». Получается «располагаете полутора тысячами рублей»."]},{"author":"И. Рубанов","question":"Вот пять предложений:\n1. За текущей водой и горящим огнём можно наблюдать <strong>часами</strong>.\n2. Той осенью <strong>сутками</strong> шёл дождь.\n3. <strong>Днями и ночами</strong>, почти не останавливаясь, работал заводской конвейер.\n4. <strong>Ночами</strong> пассажиров развозил с вокзала по городу специальный автобус.\n5. Порой обещанного приходится ждать <strong>годами</strong>.\nВ каком предложении выделенный фрагмент текста используется не в том смысле, что в четырёх остальных?","choices":["в первом","во втором","в третьем","в четвёртом","в пятом."],"key":"Г","review":["Как долго или когда","В выражениях «часами», «сутками», «днями и ночами» и «годами» речь о том, как долго длится действие.","«Ночами пассажиров развозил автобус» значит «по ночам». Здесь выражение отвечает на вопрос «когда?», а не о длительности поездки."]},{"author":"И. Шаронов","question":"Какое из выражений совсем не похоже по смыслу на другие?","choices":["<em>недалёкого ума</em>","<em>пороху не выдумает</em>","<em>не лыком шит</em>","<em>звёзд с неба не хватает</em>","<em>толоконный лоб</em>."],"key":"В","review":["О способностях человека","«Недалёкого ума», «пороху не выдумает», «звёзд с неба не хватает» и «толоконный лоб» могут сказать о человеке, которого считают не слишком умным.","«Не лыком шит» — положительная оценка. О человеке говорят, что он не простак, способен постоять за себя или с чем-то справиться."]},{"author":"О. Подлесская","question":"<em>Самой</em> _____ <em>книгой в мире является Библия</em>.","choices":["<em>переведомой</em>","<em>переводимой</em>","<em>переводящей</em>","<em>переводной</em>","среди ответов (А)–(Г) нет правильного."],"key":"Б","review":["Книга в переводах","Библию переводят на другие языки. Слово перед «книгой» должно обозначать объект этого действия.","От «переводить» получаем страдательное причастие «переводимая». В творительном падеже «самой переводимой книгой»."]},{"author":"М. Рубинштейн","question":"А. П. Бородин был не только композитором, но и крупным химиком. Какой романс ему в шутку приписывают?","choices":["«Отвори потихоньку калитку»","«Натворил я дел»","«Растворил я окно»","«Затворил я окно»","«Затворю я ставни»."],"key":"В","review":["Романс химика","В обычной фразе «растворить окно» значит открыть его настежь. У химика слово «растворить» вызывает и другую ассоциацию.","Так говорят о веществе, которое превращают в раствор. Романс «Растворил я окно» подходит для шутки о композиторе-химике."]},{"author":"И. Иткин","question":"Македонский язык — один из южнославянских языков. Что означает македонский глагол <em>свири</em>?","choices":["‘шептать’","‘хрюкать’","‘злиться’","‘рано вставать по утрам’","‘играть на музыкальном инструменте’."],"key":"Д","review":["Одно слово по-македонски","Подбери русское слово, похожее на «свири», например «свирель». Это музыкальный инструмент.","Глагол «свири» означает «играть на музыкальном инструменте». Связь со свирелью подсказала область значения."]},{"author":"Е. Муравенко","question":"Какие из глаголов: <em>нести</em>, <em>носить</em> и <em>сунуть</em> — содержат одинаковый набор согласных звуков?","choices":["никакие","только <em>нести</em> и <em>носить</em>","только <em>нести</em> и <em>сунуть</em>","только <em>носить</em> и <em>сунуть</em>","все."],"key":"А","review":["Твёрдые и мягкие согласные","В словах «нести» и «носить» похожи буквы, но начальный Н в первом мягкий, а во втором твёрдый.","В «сунуть» начальный С твёрдый, а в двух других словах С в этой позиции мягкий. Ни одна пара не даёт одинакового звукового набора."]},{"author":"И. Рубанов","question":"<em>Виноград</em>____, <em>овоще</em>____, <em>хлебо</em>____. Подставьте отсутствующие буквы так, чтобы получились названия сельскохозяйственных профессий.","choices":["-<em>овод</em>, -<em>роб</em>, -<em>роб</em>","-<em>арь</em>, -<em>роб</em>, -<em>вод</em>","-<em>арь</em>, -<em>вод</em>, -<em>роб</em>","-<em>овод</em>, -<em>вод</em>, -<em>вод</em>","-<em>ороб</em>, -<em>вод</em>, -<em>вод</em>."],"key":"В","review":["Названия профессий","Тот, кто занимается выращиванием винограда, — «виноградарь», а кто выращивает овощи — «овощевод».","Того, кто трудится над выращиванием хлебных культур, называют «хлебороб». Нужны части «-арь», «-вод», «-роб»."]},{"author":"А. Пиперски","question":"По какому предлогу можно почти с полной уверенностью определить, форма какого слова будет идти дальше?","choices":["<em>во</em>","<em>ко</em>","<em>около</em>","<em>ото</em>","<em>передо</em>."],"key":"Д","review":["Форма после предлога","После «во», «ко», «около» и «ото» могут стоять формы многих разных слов: «во вторник», «ко времени», «около дома», «ото льда».","«Передо» особенно часто встречается в сочетании «передо мной». Оно лучше всего подсказывает следующее слово."]},{"author":"И. Рубанов","question":"Какое из этих слов не прижилось в русском языке в качестве названия числа?","choices":["<em>пи</em>","<em>миллион</em>","<em>миллиард</em>","<em>триллион</em>","<em>триллиард</em>."],"key":"Д","review":["Названия больших чисел","Среди обычных названий чисел есть «пи», «миллион», «миллиард» и «триллион». Слово «пи» обозначает особое число, но тоже употребляется.","«Триллиард» иногда встречается в системах наименования очень больших чисел. В обычном русском употреблении это название не закрепилось."]},{"author":"И. Иткин","question":"Какое из этих сочетаний не обладает той особенностью, которой обладают остальные?","choices":["<em>за чем</em>","<em>за тем</em>","<em>при чём</em>","<em>от того</em>","<em>до того</em>."],"key":"Д","review":["Когда слова пишут слитно","Сравни «за чем» и «зачем», «за тем» и «затем», «при чём» и «причём», «от того» и «оттого». У каждой пары есть слитное слово и раздельное сочетание.","У «до того» такого слитного соответствия нет. Пишем два слова."]},{"author":"Б. Иомдин","question":"В каком из примеров автор написал не то, что собирался?","choices":["<em>Вчера с часовым поездом отбыла в Петербург группа студентов московского университета в составе 40 человек.</em> («Русское слово»)","<em>Утренний поезд отменили. Вернулся на вокзал к часовому поезду ― опять неудача, ― опоздал на 2 минуты.</em> (О. Бессарабова)","<em>При отсутствии пометки в билете нужно ориентироваться на основной часовой поезд государства.</em> (И. Кулюта)","<em>Сегодня предполагал остаться в городе для заседания Военного совета; но утром получил телеграмму, чтобы приехать в Царское Село с часовым поездом.</em> (Д. Милютин)","<em>На вечерний поезд, однако, они не попали, так как Неелова задержали дела со старостой, и отъезд был отложен до другого дня до часового поезда.</em> (Н. Гейнце))."],"key":"В","review":["Поезд или пояс","В исторических текстах «часовой поезд» — поезд, который отправляется в час. Поэтому оно осмысленно в рассказах о вокзале и отъезде.","При указании времени на билете нужно учитывать «часовой пояс», а не «часовой поезд». Автор третьего отрывка перепутал слова."]},{"author":"О. Подлесская","question":"Четыре выражения имеют одну общую редкую особенность, а одно нет. Какое?","choices":["<em>отбрось робость</em>","<em>фиалка халифа</em>","<em>автодорога дороговата</em>","<em>запонка напоказ</em>","<em>ужимка мужика</em>."],"key":"Б","review":["Буквы внутри пары","Сравни наборы букв в словах «отбрось» и «робость», «автодорога» и «дороговата», «запонка» и «напоказ», «ужимка» и «мужика». В каждой паре они совпадают.","В «фиалка» есть К, а в «халифа» — Х. В этой паре слова не анаграммы."]},{"author":"Е. Муравенко","question":"Какой глагол образован не так, как остальные?","choices":["<em>мошенничать</em>","<em>лентяйничать</em>","<em>лодырничать</em>","<em>подхалимничать</em>","<em>лоботрясничать</em>."],"key":"А","review":["Основа глагола","«Лентяйничать», «лодырничать», «подхалимничать» и «лоботрясничать» образованы от названий людей без конечного «-ник»: лентяй, лодырь, подхалим, лоботряс.","«Мошенничать» связано со словом «мошенник». При образовании глагола конечное К основы чередуется с Ч."]},{"author":"Е. Муравенко","question":"Все приведённые глаголы неоднозначны. Но только в одном случае глаголы с разным значением относятся к одному виду. В каком?","choices":["<em>искупать</em>","<em>покидать</em>","<em>затопить</em>","<em>слетать</em>","<em>проводить</em>."],"key":"В","review":["Одинаковое написание глаголов","«Искупать вину» — процесс, «искупать ребёнка» — завершённое действие. Так же виды различаются у значений «покидать», «слетать» и «проводить».","«Затопить комнату водой» и «затопить печь» оба отвечают на вопрос «что сделать?». Оба глагола совершенного вида."]},{"author":"А. Пиперски","question":"Какое из этих прилагательных по происхождению не связано с глаголом?","choices":["<em>вялый</em>","<em>смелый</em>","<em>удалой</em>","<em>усталый</em>","<em>целый</em>."],"key":"Д","review":["Происхождение прилагательных","«Вялый» можно связать с «вянуть», «смелый» — со «сметь», «удалой» — с «удаться», «усталый» — с «устать».","«Целый» — старое прилагательное. Глагол «целеть» происходит от него, поэтому само оно не образовано от глагола."]},{"author":"И. Иткин","question":"Сколько в русском алфавите букв, названия которых начинаются на букву <em>Э</em>?","choices":["одна","три","четыре","шесть","семь."],"key":"Д","review":["Названия букв на Э","При подсчёте учитываем название самой Э, а не только согласных. Посмотри, с какого звука начинается название каждой буквы.","Таких названий семь: «э», «эф», «эль», «эм», «эн», «эр», «эс»."]},{"author":"С. Дьяченко","question":"Какой из этих глаголов в древнерусском языке имел значение ‘ударить, убить’?","choices":["<em>осквернить</em>","<em>напакостить</em>","<em>наградить</em>","<em>заразить</em>","<em>защитить</em>."],"key":"Г","review":["Древнее значение глагола","Смысл слова может измениться. Современное «заразить» чаще всего означает передать инфекцию.","У древнерусского «заразити» было значение «поразить, ударить, убить». Поэтому выбираем «заразить»."]},{"author":"С. Сай","question":"«На крылечке тёмного и гнилого строения, вероятно бани, сидел дюжий парень с гитарой и не без удали напевал известный романс:\n<em>Э — я фа пасатыню удаляюсь\nАта прекарасаных _____ мест… и проч.</em>»\nКакое слово в цитате из рассказа И. С. Тургенева «Контора» мы заменили на прочерк?","choices":["<em>дешенехеса</em>","<em>нешеседеха</em>","<em>седешенеха</em>","<em>хесенедеша</em>","<em>шесехенеда</em>."],"key":"В","review":["Романс у Тургенева","У певца слова растянуты: например, обычное «прекрасных» стало «прекарасаных». Сначала узнаем нормальное выражение «от прекрасных здешних мест».","Из предложенных вариантов ближе всего к цепочке согласных в «здешних» запись «седешенеха». Так и передано в цитате."]},{"author":"О. Подлесская","question":"Вы, наверное, знаете, что слово <em>тетрадь</em> — греческого происхождения, восходит к корню со значением ‘четыре’. А какое русское слово восходит к греческому ‘сложенный вдвое’?","choices":["<em>паспорт</em>","<em>грамота</em>","<em>диплом</em>","<em>удостоверение</em>","<em>аттестат</em>."],"key":"В","review":["Документ, сложенный вдвое","Слова о двух частях могут начинаться с греческого «ди-». В каком названии документа сохранилось такое начало?","«Диплом» восходит к греческому слову о сложенном вдвое документе. Остальные варианты имеют другое происхождение."]}], {"year":2021,"grade":"8-9","tasksFile":"8-9.pdf","answersFile":"8-9-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2021-1.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
